function exportErrorMessage(message){const text=String(message||'3D export failed.');if(!/zero area|triangle collapsed/i.test(text))return text;return text.replace(/Try smoother tracing\.?/i,'').replace(/\.\s*\./g,'.').trim()+' Increase Maximum colors (for example, from 4 to 6 or 8), then retrace your artwork and rebuild the 3D model. Increasing colors can help separate merged details.';}
function stlSettings(){const values={includeSTL:$('exportFormats').value==='all',widthMM:+$('modelWidth').value,baseMM:+$('baseHeight').value,topMM:+$('topHeight').value};for(const [key,n]of Object.entries(values).filter(([key])=>key!=='includeSTL'))if(!Number.isFinite(n)||n<=0||n>({widthMM:500,baseMM:20,topMM:10}[key]))throw Error('Use a width of 1–500 mm, base of 0.1–20 mm and raised layer of 0.1–10 mm.');if(values.widthMM<1||values.baseMM<.1||values.topMM<.1)throw Error('Model dimensions are too small.');return values;}
function clearSTL(item){for(const key of ['stlUrl','partsUrl','threeMFUrl'])if(item[key])URL.revokeObjectURL(item[key]);item.threeMFUrl=null;item.threeMF=null;item.stlUrl=null;item.partsUrl=null;item.stl=null;item.stlError=null;}
function makeSTL(svg,settings,onProgress=()=>{}){return new Promise((resolve,reject)=>{const doc=new DOMParser().parseFromString(svg,'image/svg+xml');const box=(doc.documentElement.getAttribute('viewBox')||'').split(/[ ,]+/).map(Number);const metadata=doc.querySelector('#coasterlab-trace');let rimSealPx=0,edgeRemovedD='',perimeterD='',perimeterMaskD='',perimeterFill='',perimeterRimPx=0;if(metadata){try{const trace=JSON.parse(metadata.textContent);rimSealPx=Math.max(0,+trace.rimSealPx||0);edgeRemovedD=trace.edgeCleanup?.removedRegionsD||'';if(trace.perimeterPathID){perimeterD=doc.getElementById(trace.perimeterPathID)?.getAttribute('d')||'';perimeterMaskD=doc.getElementById(trace.perimeterMaskPathID)?.getAttribute('d')||'';perimeterFill=trace.perimeterFill;perimeterRimPx=+trace.perimeterRimPx||0;}}catch{}}const paths=[...doc.querySelectorAll('path')].filter(p=>!p.closest('defs')&&p.getAttribute('fill')!=='none'&&p.getAttribute('opacity')!=='0').map(p=>({d:p.getAttribute('d'),fill:p.getAttribute('fill')||'#000000',fillRule:p.getAttribute('fill-rule')||'nonzero'}));const worker=new Worker('stl-worker.48715ff0fe7f.js',{type:'module'});const timer=setTimeout(()=>{worker.terminate();reject(Error('STL generation timed out. Try fewer colors or smoother tracing.'));},180000);const finish=()=>{clearTimeout(timer);worker.terminate();};worker.onmessage=e=>{if(e.data.progress){onProgress(e.data.progress);return;}finish();e.data.error?reject(Error(e.data.error)):resolve(e.data);};worker.onerror=e=>{finish();reject(Error('Could not load the 3D engine. Serve the app over HTTP/HTTPS and allow WebAssembly.'));};worker.postMessage({paths,rimSealPx,edgeRemovedD,perimeterD,perimeterMaskD,perimeterFill,perimeterRimPx,viewWidth:box[2],...settings});});}
async function generateItemSTL(item,settings){clearSTL(item);try{const result=await makeSTL(item.svg,settings,message=>{$('notice').textContent=message;});if(result.warnings)result.warnings=result.warnings.map(exportErrorMessage);item.stl=result;if(!batchTemplate)await batchProfilePromise;if(!batchTemplate)throw Error('Printer profile is unavailable. Load a Bambu project template and rebuild.');$('notice').textContent='Packing Bambu 3MF…';item.threeMF=await packProject([{file:item.file,stl:result}],batchTemplate);item.threeMFUrl=URL.createObjectURL(new Blob([item.threeMF],{type:'model/3mf'}));if(result.combined)item.stlUrl=URL.createObjectURL(new Blob([result.combined.buffer],{type:'model/stl'}));if(settings.includeSTL)item.partsUrl=URL.createObjectURL(new Blob([await packParts(item,result)],{type:'application/zip'}));}catch(e){clearSTL(item);item.stlError=exportErrorMessage(e.message);} }
async function generateAllSTLs(){if(busy)return;const ready=items.filter(i=>i.svg&&!i.traceStale);if(!ready.length)return;let settings;try{settings=stlSettings();}catch(e){$('notice').textContent=e.message;return;}busy=true;render();for(let n=0;n<ready.length;n++){$('notice').textContent='Building 3D model '+(n+1)+' of '+ready.length+'…';await generateItemSTL(ready[n],settings);render();}busy=false;const failed=ready.filter(i=>i.stlError).length;$('notice').textContent=failed?ready.filter(i=>i.stlError).map(i=>i.file.name+': '+i.stlError).join(' | '):'3D models ready: '+settings.baseMM+' mm base + '+settings.topMM+' mm raised image.';render();}
$('buildSTL').onclick=generateAllSTLs;
$('downloadSTL').onclick=()=>{const ready=items.filter(i=>i.stl&&i.stl.combined);if(ready.length===1){download(ready[0].stlUrl,ready[0].outname.replace(/\.svg$/,'.stl'));return;}const files={};for(const item of ready){const name=item.outname.replace(/\.svg$/,'');files[name+'.3mf']=item.threeMF;files[name+'.stl']=new Uint8Array(item.stl.combined.buffer);files[name+'-color-parts.zip']=partsArchive(item,item.stl);}const url=URL.createObjectURL(new Blob([fflate.zipSync(files,{level:6})],{type:'application/zip'}));download(url,'coasterlab-3d-models.zip');setTimeout(()=>URL.revokeObjectURL(url),30000);};
for(const id of ['modelWidth','baseHeight','topHeight','exportFormats'])$(id).addEventListener('input',()=>{for(const item of items)clearSTL(item);render();$('notice').textContent='3D dimensions changed. Click Build / rebuild STL to apply.';});

$('download3MF').onclick=()=>{const ready=items.filter(i=>i.threeMF);if(ready.length>1){downloadBatchProject();return;}if(ready.length===1){download(ready[0].threeMFUrl,ready[0].outname.replace(/\.svg$/,'.3mf'));return;}const files={};for(const item of ready)files[item.outname.replace(/\.svg$/,'.3mf')]=item.threeMF;const url=URL.createObjectURL(new Blob([fflate.zipSync(files,{level:6})],{type:'application/zip'}));download(url,'coasterlab-bambu-models.zip');setTimeout(()=>URL.revokeObjectURL(url),30000);};
